<?php
declare(strict_types=1);
require_once __DIR__.'/legacy-migration/WorkforceCatalogReconciliationCandidate.php';
function reconciliationEnv(string$n):string{$v=getenv($n);if($v===false||$v==='')throw new RuntimeException("Missing {$n}");return$v;}
$path=$argv[1]??null;$apply=in_array('--apply',$argv,true);if(!is_string($path)||!is_file($path))throw new InvalidArgumentException('Usage: php reconcile-workforce-catalog-candidate.php <reviewed-evidence.json> [--apply]');
if(reconciliationEnv('FMONITOR_LOCAL_PILOT_ACK')!=='local-pilot-only')throw new DomainException('LOCAL_PILOT_GUARD_REQUIRED');
$manifestPath=reconciliationEnv('FMONITOR_PILOT_ACTIVE_MANIFEST');$manifest=json_decode((string)file_get_contents($manifestPath),true,flags:JSON_THROW_ON_ERROR);$prefix=(string)($manifest['processPrefix']??'');$generation=filter_var($manifest['generation']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$expectedGeneration=filter_var(reconciliationEnv('FMONITOR_EXPECTED_GENERATION'),FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$expectedPrefix=reconciliationEnv('FMONITOR_EXPECTED_PROCESS_PREFIX');
if($generation===false||$expectedGeneration===false||$generation!==$expectedGeneration||$prefix!==$expectedPrefix||preg_match('/^[A-Za-z0-9_]+$/D',$prefix)!==1)throw new DomainException('ACTIVE_GENERATION_GUARD_FAILED');
