$input=json_decode((string)file_get_contents($path),true,flags:JSON_THROW_ON_ERROR);$evaluation=WorkforceCatalogReconciliationCandidate::evaluate($input['legacyMatches']??[],$input['bitrixMatches']??[],reconciliationEnv('FMONITOR_WORKFORCE_TARGET_HASH'),reconciliationEnv('FMONITOR_PROFILE_HASH_KEY'));
$db=new mysqli(reconciliationEnv('FMONITOR_DB_HOST'),reconciliationEnv('FMONITOR_DB_USER'),reconciliationEnv('FMONITOR_DB_PASSWORD'),$dbName,(int)reconciliationEnv('FMONITOR_DB_PORT'));$db->set_charset('utf8mb4');
try{$local=($evaluation['eligible']??false)?WorkforceCatalogReconciliationCandidate::inspectLocal($db,$prefix,$evaluation):['state'=>'not_evaluated','applyAllowed'=>false];$public=array_diff_key($evaluation,['candidate'=>true]);if(!$apply){echo json_encode(['mode'=>'dry-run']+$public+['localState'=>$local['state'],'applyAllowed'=>$evaluation['eligible']&&$local['applyAllowed']],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";exit($evaluation['eligible']&&$local['applyAllowed']?0:2);}if(!$local['applyAllowed'])throw new DomainException('WORKFORCE_RECONCILIATION_APPLY_NOT_ALLOWED');$result=WorkforceCatalogReconciliationCandidate::apply($db,$prefix,$evaluation,reconciliationEnv('FMONITOR_OPERATION_ID'),reconciliationEnv('FMONITOR_OBSERVED_AT'));echo json_encode(['mode'=>'apply']+$result+['identifiersExposed'=>false],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";}finally{$db->close();}
